class Solution {
public:
    int maxConsecutive(int bottom, int top, vector<int>& special) {
        int n = special.size();
        long long R = (long long)top - bottom + 1;
        long long w = (R + n - 1) / n;  // ceiling division
        vector<long long> bmin(n, LLONG_MAX), bmax(n, LLONG_MIN);
        for (int f : special) {
            int i = (int)(((long long)f - bottom) / w);
            bmin[i] = min(bmin[i], (long long)f);
            bmax[i] = max(bmax[i], (long long)f);
        }
        long long ans = 0, prev = (long long)bottom - 1;
        for (int i = 0; i < n; i++) {
            if (bmin[i] == LLONG_MAX) continue;
            ans = max(ans, bmin[i] - prev - 1);
            prev = bmax[i];
        }
        ans = max(ans, (long long)top - prev);
        return (int)ans;
    }
};
